solution.src/math.js:
function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function inverseLerp(a, b, value) {
  return a === b ? 0 : (value - a) / (b - a);
}

module.exports = { clamp, lerp, inverseLerp };
